#include <iostream>
#include <vector>
using namespace std;

vector<vector<int>> tree;
vector<int> parent, depth, subtree;

void dfs(int vertex, int par) {
    parent[vertex] = par;
    subtree[vertex] = 1;
    for (int next : tree[vertex]) {
        if (next == par) continue;
        depth[next] = depth[vertex] + 1;
        dfs(next, vertex);
        subtree[vertex] += subtree[next];
    }
}

int main() {
    int n;
    cin >> n;
    tree.assign(n + 1, {});
    parent.assign(n + 1, 0);
    depth.assign(n + 1, 0);
    subtree.assign(n + 1, 0);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }
    dfs(1, 0);
    for (int i = 1; i <= n; ++i) cout << depth[i] << ' ' << subtree[i] << '\n';
    return 0;
}
